"use client";

import businessStyles from "@/components/business.module.css";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { ParsePendingButton } from "@/components/parse-pending-button";
import { userFeedback } from "@/lib/user-feedback";
import { Button } from "@/components/ui/button";
import { Dialog } from "@/components/ui/dialog";
import { FileUploadTrigger } from "@/components/ui/file-upload-trigger";
import { FeedbackMessage } from "@/components/ui/feedback-message";

export function SoUploadForm({ className }: { className?: string }) {
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [fileName, setFileName] = useState("");
  const [uploaded, setUploaded] = useState<{ id: string; name: string } | null>(null);
  const [removing, setRemoving] = useState(false);
  const [confirmingRemoval, setConfirmingRemoval] = useState(false);
  const router = useRouter();

  async function upload(file: File) {
    if (busy) return;
    setBusy(true);
    setMessage("");
    try {
      const data = new FormData();
      data.set("file", file);
      const response = await fetch("/api/orders/upload", { method: "POST", body: data });
      if (response.ok) {
        const result = await response.json() as { id: string };
        setUploaded({ id: result.id, name: file.name });
        setMessage(`“${file.name}”已上传。完成全部上传后，可统一识别订单信息。`);
        setFileName("");
      } else {
        setMessage("上传未完成，请确认选择的是可打开的 PDF 后重试。");
      }
    } catch {
      setMessage(userFeedback.network);
    } finally {
      setBusy(false);
    }
  }

  async function removeUploaded() {
    if (!uploaded || removing) return;
    setRemoving(true);
    try {
      const response = await fetch(`/api/orders/${uploaded.id}?pendingOnly=1`, { method: "DELETE" });
      if (response.ok) {
        setMessage(`“${uploaded.name}”已删除。`);
        setUploaded(null);
        setConfirmingRemoval(false);
        router.refresh();
      } else setMessage("该 SO 已进入识别流程，无法从上传区删除。");
    } catch {
      setMessage(userFeedback.network);
    } finally {
      setRemoving(false);
    }
  }

  return (
    <section className={[businessStyles["so-upload"], className].filter(Boolean).join(" ")}>
      <h3>导入 SO</h3>
      <div className={businessStyles["so-upload__actions"]}>
        <FileUploadTrigger variant="secondary" className={businessStyles["so-upload__trigger"]} name="file" accept="application/pdf" busy={busy} onChange={event => { const file = event.target.files?.[0]; event.target.value = ""; if (file) { setFileName(file.name); void upload(file); } }}>{busy ? "正在上传…" : "上传 SO 文件"}</FileUploadTrigger>
        <ParsePendingButton variant="primary" />
        <span className={businessStyles["so-upload__hint"]}>{busy && fileName ? `正在上传：${fileName}` : "选择 PDF 后自动上传"}</span>
      </div>
      {message && <div className={businessStyles["so-upload__message"]}><FeedbackMessage>{message}</FeedbackMessage>{uploaded && <Button type="button" variant="danger" className={businessStyles["so-upload__remove"]} disabled={removing} onClick={() => setConfirmingRemoval(true)}>删除此上传</Button>}</div>}
      {confirmingRemoval && uploaded && <Dialog tone="danger" title="确认删除此上传？" closeDisabled={removing} onClose={() => setConfirmingRemoval(false)} actions={<><Button type="button" variant="neutral" wide="mobile" disabled={removing} onClick={() => setConfirmingRemoval(false)}>返回</Button><Button type="button" variant="danger" wide="mobile" disabled={removing} onClick={removeUploaded}>{removing ? "正在删除…" : "确认删除"}</Button></>}><p>将删除“{uploaded.name}”及其待识别 SO，且无法恢复。</p></Dialog>}
    </section>
  );
}
