"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { userFeedback } from "@/lib/user-feedback";
import { Button } from "@/components/ui/button";
import buttonStyles from "@/components/action-button.module.css";
import { Dialog } from "@/components/ui/dialog";
export function DeleteOrderButton({ orderId, returnToOrders = false }: { orderId: string; returnToOrders?: boolean }) { const [confirming, setConfirming] = useState(false); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); const router = useRouter(); async function remove() { if (busy) return; setBusy(true); setMessage(""); try { const response = await fetch(`/api/orders/${orderId}`, { method: "DELETE" }); if (response.ok) { if (returnToOrders) router.push("/orders"); else router.refresh(); return; } setMessage("当前订单已有后续业务记录，暂时无法删除。"); } catch { setMessage(userFeedback.network); } finally { setBusy(false); } } return <><Button type="button" variant="danger" className={buttonStyles.statusAction} onClick={() => setConfirming(true)}>删除 SO</Button>{confirming && <Dialog tone="danger" title="确认删除此 SO？" message={message} closeDisabled={busy} onClose={() => setConfirming(false)} actions={<><Button type="button" variant="neutral" wide="mobile" disabled={busy} onClick={() => setConfirming(false)}>返回</Button><Button type="button" variant="danger" wide="mobile" disabled={busy} onClick={remove}>{busy ? "正在删除…" : "确认删除"}</Button></>}><p>将删除该订单及其上传文件。若已有后续业务记录，系统会阻止删除。</p></Dialog>}</>; }
