"use client";
import { usePathname, useSearchParams } from "next/navigation";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { FeedbackMessage } from "@/components/ui/feedback-message";
import styles from "./parse-pending-button.module.css";

export function ParsePendingButton({
  orderId,
  compact = false,
  variant = "secondary",
}: {
  orderId?: string;
  compact?: boolean;
  variant?: "primary" | "secondary";
}) {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const [state, setState] = useState<"idle" | "running" | "success" | "error">(
    "idle",
  );
  const [message, setMessage] = useState("");

  async function run() {
    setState("running");
    setMessage("正在识别已上传 SO 中的订单信息，请稍候…");
    try {
      const response = await fetch("/api/orders/parse", {
        method: "POST",
        headers: orderId ? { "content-type": "application/json" } : undefined,
        body: orderId ? JSON.stringify({ orderId }) : undefined,
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error("订单信息暂未识别完成，请稍后重试。");
      setState(result.failedCount ? "error" : "success");
      setMessage(
        result.failedCount
          ? `已识别 ${result.processedCount || 0} 份 SO；另有 ${result.failedCount} 份未完成，请在订单列表中打开后查看。`
          : result.processedCount
            ? `已识别 ${result.processedCount} 份 SO，订单列表已更新。`
            : "没有需要识别的 SO。 ",
      );
      const query = searchParams.toString();
      window.location.replace(`${pathname}${query ? `?${query}` : ""}`);
    } catch (error) {
      setState("error");
      setMessage(
        error instanceof Error
          ? error.message
          : "订单信息暂未识别完成，请稍后重试。",
      );
    }
  }

  return (
    <div className={compact ? styles.compact : styles.actions}>
      <Button
        variant={variant}
        onClick={run}
        disabled={state === "running"}
      >
        {state === "running"
          ? "识别中…"
          : orderId
            ? "识别此 SO"
            : "识别订单信息"}
      </Button>
      {message && (!compact || state === "error") && (
        <FeedbackMessage as="span" tone={state === "error" ? "error" : state === "success" ? "success" : "info"}>{message}</FeedbackMessage>
      )}
    </div>
  );
}
